//! Error pages and redirects, from whichever layer would really produce
//! them: the front server or the application framework.

use http::StatusCode;
use minijinja::context;

use crate::catalog::to_crlf;
use crate::persona::Frontend;
use crate::render::doc::{Doc, Origin, ext_of};
use crate::render::php;
use crate::render::scope::Scope;

fn reason(status: StatusCode) -> &'static str {
    status.canonical_reason().unwrap_or("Error")
}

/// A page generated by the front server itself (`servers/<id>/error.html.j2`).
pub fn server_error(scope: &Scope, status: StatusCode, method: &str) -> Doc {
    let body = server_page(scope, "error.html.j2", context! { status => status.as_u16(), reason => reason(status), method => method });
    let ct = (!body.is_empty()).then(|| server_page_type(scope));
    Doc::new(Origin::Server, ct.as_deref(), body).status(status)
}

/// A server-issued redirect (a directory without its trailing slash, ...).
pub fn server_redirect(scope: &Scope, location: &str) -> Doc {
    let body = server_page(scope, "redirect.html.j2", context! { location => location });
    let ct = (!body.is_empty()).then(|| server_page_type(scope));
    Doc::new(Origin::Server, ct.as_deref(), body).status(StatusCode::MOVED_PERMANENTLY).header("location", location)
}

/// Render a server page, in CRLF where that server writes CRLF.
pub fn server_page(scope: &Scope, file: &str, extra: minijinja::Value) -> String {
    let body = scope.render_or_empty(&scope.server_template(file), extra);
    if scope.world.data().server(scope.persona().frontend).crlf_pages { to_crlf(&body) } else { body }
}

fn server_page_type(scope: &Scope) -> String {
    scope.world.data().server(scope.persona().frontend).page_type.clone()
}

/// An error page produced by the framework (`stacks/<id>/error.html.j2`).
pub fn app_error(scope: &Scope, status: StatusCode, method: &str) -> Doc {
    let p = scope.persona();
    let body = scope.render_or_empty(
        &scope.stack_template("error.html.j2"),
        context! { status => status.as_u16(), reason => reason(status), method => method },
    );
    let facts = scope.world.data().stack(p.stack);
    let ct = facts.error_type.as_deref().filter(|_| !body.is_empty());
    php::prepend(scope, Doc::new(Origin::App { session: false }, ct, body).status(status))
}

/// An application redirect (login walls and the like).
pub fn app_redirect(scope: &Scope, location: &str) -> Doc {
    let body = scope.render_or_empty(&scope.stack_template("redirect.html.j2"), context! { location => location });
    Doc::new(Origin::App { session: true }, Some("text/html; charset=UTF-8"), body).status(StatusCode::FOUND).header("location", location)
}

/// Which layer answers a 404 for this path. Setups differ: most forward
/// unknown paths to the app, some serve static extensions off disk, PHP
/// boxes may refuse missing scripts in the server.
pub fn server_handles_404(scope: &Scope) -> bool {
    let p = scope.persona();
    let ext = ext_of(&scope.req.path);
    if p.frontend == Frontend::Iis {
        return p.stack.id() != "asp_net" || !ext.is_empty();
    }
    if ext == "php" {
        return !p.is_php() || !p.web.order_salt.is_multiple_of(3);
    }
    !ext.is_empty() && !matches!(ext.as_str(), "html" | "htm") && p.web.order_salt % 5 < 2
}

pub fn not_found(scope: &Scope) -> Doc {
    let p = scope.persona();
    // php-fpm's own answer when the server passes it a missing script.
    if p.is_php() && ext_of(&scope.req.path) == "php" && p.frontend != Frontend::Apache && p.web.order_salt.is_multiple_of(21) {
        return Doc::new(Origin::App { session: false }, Some("text/html; charset=UTF-8"), "File not found.\n")
            .status(StatusCode::NOT_FOUND);
    }
    if server_handles_404(scope) {
        server_error(scope, StatusCode::NOT_FOUND, "GET")
    } else {
        app_error(scope, StatusCode::NOT_FOUND, "GET")
    }
}

pub fn forbidden(scope: &Scope) -> Doc {
    server_error(scope, StatusCode::FORBIDDEN, "GET")
}
